static void add(const char*k,const char*v){int i;for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))break;if(i==item_count){if(item_count>=160)return;item_count++;STRNCPY(items[i].key,k,sizeof(items[i].key));}STRNCPY(items[i].utf8,v,sizeof(items[i].utf8));if(!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,items[i].utf8,-1,items[i].wide,256))MultiByteToWideChar(CP_UTF8,0,items[i].utf8,-1,items[i].wide,256);}
static void unescape(char*s){char*r=s,*w=s;while(*r){if(r[0]=='\\'&&r[1]=='n'){*w++='\n';r+=2;}else if(r[0]=='\\'&&r[1]=='\\'){*w++='\\';r+=2;}else *w++=*r++;}*w=0;}
static void load_file(const char*l){char path[MAX_PATH],line[512],module[MAX_PATH],*slash,*eq;FILE*f;GetModuleFileNameA(NULL,module,sizeof(module));slash=strrchr(module,'\\');if(slash)*slash=0;snprintf(path,sizeof(path),"%s\\resources\\lang\\%s.lang",module,l);f=fopen(path,"rb");if(!f){snprintf(path,sizeof(path),"resources\\lang\\%s.lang",l);f=fopen(path,"rb");}if(!f)return;while(fgets(line,sizeof(line),f)){char*out=line;if((unsigned char)out[0]==0xef)out+=3;eq=strchr(out,'=');if(!eq||out[0]=='#')continue;*eq++=0;eq[strcspn(eq,"\r\n")]=0;unescape(eq);add(out,eq);}fclose(f);}
void win32_i18n_load(const char*l){int i;item_count=0;for(i=0;fallback[i][0];i++)add(fallback[i][0],fallback[i][1]);STRNCPY(current_locale,l&&*l?l:"en-US",sizeof(current_locale));if(_stricmp(current_locale,"en-US"))load_file(current_locale);}
const char*win32_i18n_get(const char*k){int i;if(!item_count)win32_i18n_load("en-US");for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))return items[i].utf8;return k;}
const WCHAR*win32_i18n_get_w(const char*k){static WCHAR missing[64];int i;if(!item_count)win32_i18n_load("en-US");for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))return items[i].wide;MultiByteToWideChar(CP_UTF8,0,k,-1,missing,64);return missing;}
const char*win32_i18n_locale(void){return current_locale;}
#else
void win32_i18n_load(const char*l){UNUSED(l);}const char*win32_i18n_get(const char*k){return k;}const char*win32_i18n_locale(void){return "en-US";}
